<script lang="ts">
 import {t} from '#lib/i18n.ts';
 import {session,ui} from '#lib/client.svelte.ts';import{getWines}from'#lib/editorial.svelte.ts';const wines=$derived(getWines());import Icon from '#lib/components/Icon.svelte';import WineBottle from '#lib/components/WineBottle.svelte';let search=$state('');
 const notes=$derived(session.notes.filter(n=>`${wines.find(w=>w.id===n.wine)?.name} ${n.data.text} ${n.room_name}`.toLowerCase().includes(search.toLowerCase())));
 function download(){const blob=new Blob([JSON.stringify(session.notes,null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='meine-tasting-notizen.json';a.click();URL.revokeObjectURL(a.href);}
</script>
<svelte:head><title>{t('m_8917f9bf62')}</title></svelte:head>
<div class="page-content"><div class="page-heading"><div><div class="eyebrow">{t('m_6c97e40927')}</div><h1>{t('m_493fef52d7')}<span class="accent">.</span></h1><p>{t('m_430bccb2f3')}</p></div>{#if session.notes.length}<button class="button outline" onclick={download}><Icon name="download" size={16}/>{t('m_c153d50600')}</button>{/if}</div>{#if session.error}<p class="error" role="alert">{session.error}</p>{/if}{#if session.notes.length}{#if !session.user}<div class="callout" style="margin-bottom:24px"><Icon name="heart"/><div><p>{t('m_a80502cbfc')}</p><a href="/konto" class="text-button">{t('m_75fe43e7f3')}<Icon name="right" size={15}/></a></div></div>{/if}<div class="search-field" style="margin-bottom:24px"><Icon name="search"/><input aria-label={t('m_79dbddfd8c')} bind:value={search} placeholder={t('m_27fe5e0102')}/></div><div class="note-list">{#each notes as note}{@const wine=wines.find(w=>w.id===note.wine)!}<article class="note-summary"><WineBottle {wine} interactive/><div><h3>{note.wine==='rot'&&note.room_settings?.redName?note.room_settings.redName:note.wine==='riesling'&&note.room_settings?.rieslingLabel?note.room_settings.rieslingLabel:wine.name}</h3><div class="meta">{note.room_name} · {new Date(note.updated_at).toLocaleDateString('de-DE')}</div><p>{note.data.text||'Keine Textnotiz'}</p><div class="tags">{#each note.data.aromas||[] as aroma}<span class="tag">{aroma}</span>{/each}</div><div class="stars" aria-label={note.data.rating+' von 5 Sternen'}>{#each [1,2,3,4,5] as star}<Icon name="star" size={14} fill={star<=note.data.rating?'currentColor':'none'}/>{/each}</div></div><a class="text-button" href={'/tasting/'+note.room+'?wine='+note.wine+'&notes=1'}>{t('m_104f3bfdc3')}<Icon name="external" size={15}/></a></article>{/each}</div>{#if !notes.length}<p class="muted" style="padding:25px">{t('m_4e9440bec7')}</p>{/if}{:else if !session.loaded}<div class="loading-state"><Icon name="loader"/>{t('m_c01776ed8f')}</div>{:else}<div class="empty-state"><span class="teaser-icon lilac"><Icon name="notes" size={28}/></span><h2>{t('m_2f8079851f')}</h2><p>{t('m_13a770cc54')}</p><button class="button primary" onclick={()=>ui.joinOpen=true}>{t('m_dd9c0a53c8')}<Icon name="right" size={17}/></button></div>{/if}</div>
